{"command": "cd /workspace && python3 - <<'EOF'
import json
runs=[json.loads(l) for l in open('out/cde_runs.jsonl')]
print("total runs:", len(runs))
last={}
for r in runs: last[r['target_id']]=r
for t in sorted(last):
    r=last[t]
    print(f"{t} | last cmd: {r['cmd']:<28} | CDE {r['cde_level']} | est {r['nc_casualty_estimate']} | basis {r['occupancy_basis']} | {r['approval_authority']} | NSL: {r['nsl_within_cer']}")
EOF"}

{"command": "cd /workspace && head -20 out/strike_package.md && echo "..." && sed -n '/## Notes for the CDE Validation Officer/,$p' out/strike_package.md | head -20 && echo "=== jsonl (worksheets of record) ===" && python3 -c "
import json
last={}
for l in open('out/cde_runs.jsonl'): r=json.loads(l); last[r['target_id']]=r
for t in sorted(last):
    r=last[t]; print(f\"{t}  CDE {r['cde_level']}  est {r['nc_casualty_estimate']}  NCV {r['ncv']}  basis {r['occupancy_basis']:8s} {r['approval_authority']:40s} cmd='{r['cmd']}'  {r['run_at']}\")""}

